// Estado para el tab activo
const [activeMainTab, setActiveMainTab] = useState('sql');

const [communicationsSummary, setCommunicationsSummary] = useState(null);
const [loadingCommunications, setLoadingCommunications] = useState(false);

const loadCommunications = useCallback(async () => {
  setLoadingCommunications(true);
  try {
    const response = await api.get('/integrations-center/communications');
    setCommunicationsSummary(response.data?.data || null);
  } catch (error) {
    console.error('Error cargando Comunicaciones:', error);
    toast.error('No se pudo cargar Comunicaciones');
  } finally {
    setLoadingCommunications(false);
  }
}, []);

  if (activeMainTab === 'api-factory') {
    loadApiFactory();
  }
  if (activeMainTab === 'communications') {
    loadCommunications();
  }
}, [activeMainTab, loadCoreAuditLog, loadApiFactory, loadCommunications]);
